```python
class AccountService:
    def __init__(self) -> None:
        # maps normalized email -> {password, is_admin}
        self._accounts = {}
        # maps reset token -> target email (one-time use)
        self._reset_tokens = {}

    def _normalize_email(self, email: str) -> str:
        return email.strip().lower()

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters long.")
        norm_email = self._normalize_email(email)
        if norm_email in self._accounts:
            raise ValueError("An account with this email already exists.")
        self._accounts[norm_email] = {
            "password": password,
            "is_admin": is_admin,
        }

    def login(self, email: str, password: str) -> bool:
        norm_email = self._normalize_email(email)
        account = self._accounts.get(norm_email)
        if account is None:
            return False
        return account["password"].lower() == password.lower()

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        requester_norm = self._normalize_email(requester_email)
        requester = self._accounts.get(requester_norm)
        if requester is None or not requester["is_admin"]:
            raise PermissionError("Only administrators can request password resets.")
        target_norm = self._normalize_email(target_email)
        if target_norm not in self._accounts:
            raise ValueError("Target account does not exist.")
        token = self._generate_token()
        self._reset_tokens[token] = target_norm
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        if len(new_password) < 8:
            raise ValueError("Password must be at least 8 characters long.")
        target_email = self._reset_tokens.get(token)
        if target_email is None:
            raise ValueError("Invalid or already-used reset token.")
        # One-time use: consume the token
        del self._reset_tokens[token]
        self._accounts[target_email]["password"] = new_password

    @staticmethod
    def _generate_token() -> str:
        import secrets
        return secrets.token_urlsafe(32)
```

**Key behaviors implemented:**

- **Password length (≥8)** is enforced in both `register` and `reset_password` with `ValueError`.
- **Case-insensitive login** uses `.lower()` comparison on passwords.
- **Admin-only reset requests**: `request_password_reset` checks `is_admin` and raises `PermissionError` for non-admins (including self-requests).
- **Case-insensitive emails**: all lookups normalize via `strip().lower()`.
- **Duplicate registration** raises `ValueError`.
- **One-time tokens** are erased from the token map upon successful `reset_password`, so reuse raises `ValueError`.

